import { ATTRIBUTION_KEYS, getAttribution } from './attribution';
import { getProductById } from '../content/bridgeCatalog';

// ---------------------------------------------------------------------------------------------
// Lead submission transport, shared by the AI readiness assessment, the contact form and the Nexus
// order request.
//
// All post to the same Google Apps Script web app (integrations/ai-readiness-apps-script/Code.gs,
// URL in REACT_APP_AI_READINESS_ENDPOINT, see .env.production). The script tells them apart by
// the payload's `kind` ('contact', 'order'; assessment payloads have none) and files them in
// separate tabs of the same Google Sheet ("Leads", "Contact" and "Orders").
//
// postLead() resolves to one of three honest statuses:
//   'not_configured' -- no endpoint is set; NOTHING was sent or stored. The UI says so.
//   'sent'           -- the endpoint confirmed it saved the lead ({ "ok": true }).
//   'error'          -- the endpoint is configured but the request failed; the UI offers a retry.
//
// Transport notes (Apps Script specific):
//  - The body is JSON sent as Content-Type text/plain: a CORS "simple request" (no preflight),
//    because Apps Script web apps cannot answer a preflight OPTIONS request.
//  - Apps Script replies HTTP 200 even for its own errors, so success is only ever
//    { "ok": true } in the JSON reply; anything else is treated as a failed send.
// Nothing secret may live in this client bundle: the endpoint URL is public by nature, so spam
// protection lives server-side (honeypot, size and email validation, rate limits).
// ---------------------------------------------------------------------------------------------

const ENDPOINT = process.env.REACT_APP_AI_READINESS_ENDPOINT || '';
// Apps Script web apps can take 5-15 s on a cold start; a short timeout would show the visitor an
// error for a lead that was actually saved (and invite a duplicate retry).
const TIMEOUT_MS = 25000;

// Deliberately simple: catches typos, not a full RFC 5322 parse (the server must re-validate).
export const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
export const isValidEmail = (value) => EMAIL_PATTERN.test(value.trim());

export const isLeadEndpointConfigured = () => Boolean(ENDPOINT);

// The visit's ad attribution (captured on the landing page, even if the visitor arrived at this
// page later), then anything on the current URL, which wins. Click ids are kept for a later
// offline-conversion upload.
export const readAttribution = (funnel = {}) => {
  const { landing_path: adLandingPath, ...visit } = getAttribution() || {};
  const params = new URLSearchParams(window.location.search);
  const current = {};
  params.forEach((value, key) => { if (ATTRIBUTION_KEYS.includes(key) || key.startsWith('utm_') || key === 'ref') current[key] = value.slice(0, 300); });
  return {
    ...visit, ...funnel, ...current,
    ad_landing_path: adLandingPath || null,
    referrer: document.referrer || null,
    landing_path: window.location.pathname,
  };
};

export const newSubmissionId = () => {
  try {
    if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID();
  } catch {
    // fall through
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
};

export const postLead = async (payload) => {
  if (!ENDPOINT) return { status: 'not_configured' };

  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const response = await fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    if (!response.ok) return { status: 'error' };
    const reply = await response.json().catch(() => null);
    return { status: reply && reply.ok === true ? 'sent' : 'error' };
  } catch {
    return { status: 'error' };
  } finally {
    window.clearTimeout(timer);
  }
};

// Contact-form payload. The message travels only to the endpoint (never to analytics).
export const buildContactPayload = ({ email, message, topic = null, funnel = {}, website = '', submissionId = '' }) => ({
  kind: 'contact',
  email: email.trim(),
  message: message.trim().slice(0, 3000),
  topic,
  page: window.location.pathname,
  attribution: readAttribution(funnel),
  submittedAt: new Date().toISOString(),
  submissionId,
  website,
});

// Nexus rent / buy request (/nexus/pricing, src/components/OrderRequestForm.jsx). No payment is taken: the request is
// saved, and we confirm availability, tax and shipping and send an invoice. The quoted amounts
// travel with it so the sheet shows exactly what the visitor saw (offerVersion says which terms).
export const buildOrderPayload = ({
  email, country = '', sector = '', offer, months = null, quote = null,
  offerVersion = '', funnel = {}, website = '', submissionId = '',
}) => ({
  kind: 'order',
  email: email.trim(),
  country: country.trim().slice(0, 80),
  sector,
  offer,
  months: offer === 'rent' ? months : null,
  quote,
  offerVersion,
  page: window.location.pathname,
  attribution: readAttribution(funnel),
  submittedAt: new Date().toISOString(),
  submissionId,
  website,
});

// Cart request (/request, src/components/bridge/CartRequestForm.jsx): one or more catalog products
// with quantities. No payment is taken: the request is saved and we confirm availability, tax and
// shipping and agree the payment method by email. Only ids and quantities are trusted by the
// server, which prices them from its own catalog; `quote.total` is what the visitor saw (null when
// the order is to be quoted) and `catalogVersion` says which prices that was.
export const buildCartPayload = ({
  email, country = '', sector = '', items, quote = null,
  catalogVersion = '', funnel = {}, website = '', submissionId = '',
}) => ({
  kind: 'cart',
  email: email.trim(),
  country: country.trim().slice(0, 80),
  sector,
  items: items.map(({ id, qty }) => ({ id, qty })),
  quote,
  catalogVersion,
  page: window.location.pathname,
  attribution: readAttribution(funnel),
  submittedAt: new Date().toISOString(),
  submissionId,
  website,
});

// Which kinds of submission the DEPLOYED Apps Script understands. Its GET reply lists them
// ({ "ok": true, "kinds": ["assessment", "contact", "order", "cart"] }), so the site can tell whether the
// script has been updated to take cart requests yet, instead of assuming. Looked up once and cached;
// [] when the answer is unknown (no endpoint, offline, slow), which callers treat as "use the safe path".
let kindsPromise = null;
export const getEndpointKinds = () => {
  if (!ENDPOINT) return Promise.resolve([]);
  if (!kindsPromise) {
    kindsPromise = new Promise((resolve) => {
      const controller = new AbortController();
      const timer = window.setTimeout(() => controller.abort(), 15000);
      fetch(ENDPOINT, { signal: controller.signal })
        .then((response) => response.json())
        .then((reply) => resolve(Array.isArray(reply && reply.kinds) ? reply.kinds : []))
        .catch(() => { kindsPromise = null; resolve([]); }) // try again on the next call
        .finally(() => window.clearTimeout(timer));
    });
  }
  return kindsPromise;
};

// A cart request written as a contact message. The contact path exists in every version of the deployed script
// (own sheet tab, owner notification with Reply-To, visitor confirmation), so a request is never lost or filed as
// something else while the script predates 'cart'. The wording carries everything the structured row would.
export const buildCartContactPayload = ({
  email, country = '', sector = '', items, quote = null,
  catalogVersion = '', funnel = {}, website = '', submissionId = '',
}) => {
  const lines = items.map(({ id, qty }) => `${qty} × ${(getProductById(id) || { name: id }).name}`).join('; ');
  const total = quote && typeof quote.total === 'number' ? `$${quote.total.toLocaleString('en-US')} ${quote.currency || 'USD'} (excl. tax and shipping)` : 'to be quoted';
  const message = [
    'Bridge request from the website (/request)',
    `Items: ${lines}`,
    `Estimated total: ${total}`,
    `Delivery country: ${country.trim().slice(0, 80)}`,
    `Sector: ${sector || '-'}`,
    `Catalog version: ${catalogVersion}`,
  ].join('\n');
  return {
    kind: 'contact',
    email: email.trim(),
    message: message.slice(0, 3000),
    topic: 'Bridge request',
    page: window.location.pathname,
    attribution: readAttribution(funnel),
    submittedAt: new Date().toISOString(),
    submissionId,
    website,
  };
};
